def my_cad_function(args):
    import os, math
    import cadquery as cq

    input_file = os.path.expanduser(args.get("input_file", ""))
    if not input_file or not os.path.exists(input_file):
        raise ValueError(f"input_file not found: {input_file}")

    wp = cq.importers.importStep(input_file)
    shape = wp.val() if hasattr(wp, "val") else wp

    # ---------------- basic vector helpers ----------------
    def v_add(a, b):
        return (a[0] + b[0], a[1] + b[1], a[2] + b[2])

    def v_sub(a, b):
        return (a[0] - b[0], a[1] - b[1], a[2] - b[2])

    def v_mul(a, s):
        return (a[0] * s, a[1] * s, a[2] * s)

    def v_dot(a, b):
        return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]

    def v_len(a):
        return math.sqrt(max(0.0, v_dot(a, a)))

    def v_unit(a):
        L = v_len(a)
        if L < 1e-12:
            return (0.0, 0.0, 0.0)
        return (a[0] / L, a[1] / L, a[2] / L)

    def v_cross(a, b):
        return (
            a[1] * b[2] - a[2] * b[1],
            a[2] * b[0] - a[0] * b[2],
            a[0] * b[1] - a[1] * b[0],
        )

    def pt_tuple(p):
        return (float(p.x), float(p.y), float(p.z))

    def project_to_plane(vec, n):
        n = v_unit(n)
        return v_sub(vec, v_mul(n, v_dot(vec, n)))

    def plane_basis(axis_dir):
        n = v_unit(axis_dir)
        if v_len(n) < 1e-12:
            n = (0.0, 1.0, 0.0)
        x_guess = (1.0, 0.0, 0.0) if abs(n[0]) < 0.9 else (0.0, 0.0, 1.0)
        u = v_unit(v_sub(x_guess, v_mul(n, v_dot(x_guess, n))))
        if v_len(u) < 1e-12:
            u = (1.0, 0.0, 0.0)
        v = v_unit(v_cross(n, u))
        return u, v, n

    def dir_to_line_angle_deg(dir_in_plane, u, v):
        x = v_dot(dir_in_plane, u)
        y = v_dot(dir_in_plane, v)
        ang = math.degrees(math.atan2(y, x))
        return ang % 180.0

    def ang_dist_180(a, b):
        d = abs(a - b) % 180.0
        return min(d, 180.0 - d)

    # ---------------- hub axis/radius detection ----------------
    def axis_from_smallest_bbox_dim(bb):
        dx, dy, dz = bb.xlen, bb.ylen, bb.zlen
        if dy <= dx and dy <= dz:
            return (0.0, 1.0, 0.0)
        if dx <= dy and dx <= dz:
            return (1.0, 0.0, 0.0)
        return (0.0, 0.0, 1.0)

    def find_hub_radius_and_axis(solids, global_center, axis_guess):
        try:
            from OCP.BRepAdaptor import BRepAdaptor_Surface
            from OCP.GeomAbs import GeomAbs_Cylinder
        except Exception:
            return None, axis_guess

        best = None  # (score, r, axis)
        ag = v_unit(axis_guess)

        for s in solids:
            for f in s.Faces():
                try:
                    ad = BRepAdaptor_Surface(f.wrapped)
                    if ad.GetType() != GeomAbs_Cylinder:
                        continue
                    cyl = ad.Cylinder()
                    r = float(cyl.Radius())
                    if r < 3.0 or r > 25.0:
                        continue
                    ax_dir = cyl.Axis().Direction()
                    ax = v_unit((float(ax_dir.X()), float(ax_dir.Y()), float(ax_dir.Z())))
                    align = abs(v_dot(ax, ag))
                    loc = cyl.Location()
                    c = (float(loc.X()), float(loc.Y()), float(loc.Z()))
                    dist = v_len(v_sub(c, global_center))
                    score = 10.0 * align - 0.10 * dist - 0.05 * abs(r - 6.5)
                    if best is None or score > best[0]:
                        best = (score, r, ax)
                except Exception:
                    continue

        if best is None:
            return None, axis_guess
        return best[1], best[2]

    # ---------------- blade direction in rotor plane ----------------
    def blade_dir_from_vertices(blade_solid, global_center, axis_dir):
        pts = []
        for vv in blade_solid.Vertices():
            p = pt_tuple(vv.Center())
            vp = project_to_plane(v_sub(p, global_center), axis_dir)
            if v_len(vp) > 1e-6:
                pts.append(vp)
        if len(pts) < 2:
            bb = blade_solid.BoundingBox()
            return (0.0, 0.0, 1.0) if bb.zlen >= bb.xlen else (1.0, 0.0, 0.0)

        max_d2 = -1.0
        best_pair = (pts[0], pts[1])
        for i in range(len(pts)):
            a = pts[i]
            for j in range(i + 1, len(pts)):
                b = pts[j]
                d = v_sub(b, a)
                d2 = v_dot(d, d)
                if d2 > max_d2:
                    max_d2 = d2
                    best_pair = (a, b)
        d = v_unit(v_sub(best_pair[1], best_pair[0]))
        return d if v_len(d) > 1e-9 else (0.0, 0.0, 1.0)

    # ---------------- thinning helpers ----------------
    def make_axis_workplane(axis_dir):
        n = v_unit(axis_dir)
        if v_len(n) < 1e-12:
            n = (0.0, 1.0, 0.0)
        x_guess = (1.0, 0.0, 0.0) if abs(n[0]) < 0.9 else (0.0, 0.0, 1.0)
        xdir = v_unit(v_sub(x_guess, v_mul(n, v_dot(x_guess, n))))
        if v_len(xdir) < 1e-12:
            xdir = (1.0, 0.0, 0.0)
        plane = cq.Plane(origin=(0, 0, 0), xDir=xdir, normal=n)
        return cq.Workplane(plane)

    def thickness_along_axis(bb, axis_dir):
        ax = (abs(axis_dir[0]), abs(axis_dir[1]), abs(axis_dir[2]))
        return ax[0] * bb.xlen + ax[1] * bb.ylen + ax[2] * bb.zlen

    def thin_central_portion_box(blade_solid, global_center, axis_dir, window_size, target_thickness=0.42):
        axis_dir = v_unit(axis_dir)
        if v_len(axis_dir) < 1e-12:
            axis_dir = (0.0, 1.0, 0.0)

        bb = blade_solid.BoundingBox()
        t0 = thickness_along_axis(bb, axis_dir)
        if t0 <= target_thickness + 1e-3:
            return blade_solid

        cutter_h = max(2.0 * t0, 120.0)
        base_wp = make_axis_workplane(axis_dir)
        window = base_wp.rect(window_size, window_size).extrude(cutter_h, both=True).val().translate(global_center)

        offset = (target_thickness / 2.0) + (cutter_h / 2.0)
        top_cutter = window.translate(v_mul(axis_dir, offset))
        bot_cutter = window.translate(v_mul(axis_dir, -offset))

        return blade_solid.cut(top_cutter).cut(bot_cutter)

    # ---------------- fillet selection ----------------
    def edge_endpoints(edge):
        vs = edge.Vertices()
        if len(vs) < 2:
            p = pt_tuple(edge.Center())
            return p, p
        return pt_tuple(vs[0].Center()), pt_tuple(vs[-1].Center())

    def fillet_edges_safe(solid, edges, radii_try):
        if not edges:
            return solid, False
        # try all at once first
        for r in radii_try:
            try:
                return cq.Workplane(obj=solid).newObject(edges).fillet(r).val(), True
            except Exception:
                pass
        # fallback: one-by-one
        s = solid
        any_ok = False
        for r in radii_try[::-1]:
            ok_this_r = False
            for e in edges:
                try:
                    s = cq.Workplane(obj=s).newObject([e]).fillet(r).val()
                    ok_this_r = True
                    any_ok = True
                except Exception:
                    pass
            if ok_this_r:
                return s, True
        return solid, any_ok

    def long_edge_segments_4groups(blade_solid, global_center, axis_dir, dlen):
        axis_dir = v_unit(axis_dir)
        dlen = v_unit(dlen)
        if v_len(dlen) < 1e-9:
            return []

        w = v_unit(v_cross(axis_dir, dlen))
        if v_len(w) < 1e-9:
            u0, v0, _ = plane_basis(axis_dir)
            w = v_unit(v_cross(axis_dir, u0))

        # collect candidate edges aligned with blade axis
        cands = []  # (abs_width, width, height, length, edge)
        for e in blade_solid.Edges():
            try:
                L = float(e.Length())
                if L < 5.0:
                    continue
                p1, p2 = edge_endpoints(e)
                de = v_unit(v_sub(p2, p1))
                if v_len(de) < 1e-12:
                    continue
                if abs(v_dot(de, dlen)) < 0.90:
                    continue
                mid = pt_tuple(e.Center())
                rel = v_sub(mid, global_center)
                width = v_dot(rel, w)
                height = v_dot(rel, axis_dir)
                cands.append((abs(width), width, height, L, e))
            except Exception:
                continue

        if not cands:
            return []

        max_abs_w = max(t[0] for t in cands)
        if max_abs_w < 1e-6:
            return []

        # keep only outermost width edges (avoid internal aligned edges)
        outer = [t for t in cands if t[0] > 0.65 * max_abs_w]
        if not outer:
            outer = cands

        groups = {"TR": [], "TL": [], "BR": [], "BL": []}
        for aw, width, height, L, e in outer:
            top = height >= 0.0
            right = width >= 0.0
            key = ("T" if top else "B") + ("R" if right else "L")
            groups[key].append((L, aw, e))

        # Keep multiple segments per group (important when the edge is split near the hub/notches)
        picked = []
        for key in ["TR", "TL", "BR", "BL"]:
            segs = groups[key]
            segs.sort(key=lambda t: (t[0], t[1]), reverse=True)
            # keep up to 8 best segments per group (usually only a few exist)
            for L, aw, e in segs[:8]:
                picked.append(e)

        # de-dup
        out = {}
        for e in picked:
            try:
                hc = e.wrapped.HashCode(1000003)
            except Exception:
                hc = id(e)
            out[hc] = e
        return list(out.values())

    # ---------------- best 3-blade spacing in mod180 ----------------
    def best_three_line_pattern(existing_angles, step=0.25):
        best = None  # (score, a, targets, missing_idx)
        a = 0.0
        while a < 60.0 - 1e-9:
            targets = [(a + 0.0) % 180.0, (a + 60.0) % 180.0, (a + 120.0) % 180.0]
            used = set()
            score = 0.0
            for ea in existing_angles:
                dists = sorted([(ang_dist_180(ea, t), i) for i, t in enumerate(targets)], key=lambda x: x[0])
                d, ti = dists[0]
                if ti in used and len(dists) > 1:
                    d, ti = dists[1]
                    score += (d * d) + 25.0
                else:
                    score += d * d
                used.add(ti)
            missing = [i for i in range(3) if i not in used]
            missing_idx = missing[0] if missing else 0
            if best is None or score < best[0]:
                best = (score, a, targets, missing_idx)
            a += step
        if best is None:
            return None, None
        _, a_best, targets_best, mi = best
        return targets_best, targets_best[mi]

    # ---------------- main ----------------
    solids = list(shape.Solids()) if hasattr(shape, "Solids") else []
    print(f"Loaded STEP: {input_file}")
    print(f"Solid count (input): {len(solids)}")
    if len(solids) < 2:
        return wp

    bb_all = shape.BoundingBox()
    global_center = pt_tuple(bb_all.center)
    axis_guess = axis_from_smallest_bbox_dim(bb_all)
    hub_r, axis_dir = find_hub_radius_and_axis(solids, global_center, axis_guess)
    if hub_r is None:
        hub_r = 6.5
        axis_dir = (0.0, 1.0, 0.0)
    axis_dir = v_unit(axis_dir)
    if v_len(axis_dir) < 1e-12:
        axis_dir = (0.0, 1.0, 0.0)

    print(f"Overall bbox center: {global_center}")
    print(f"Axis dir (hub): {axis_dir}")
    print(f"Hub radius (detected/assumed): {hub_r:.3f} mm")

    # classify blades by bbox
    blade_idxs = []
    other_idxs = []
    for i, s in enumerate(solids):
        bb = s.BoundingBox()
        long_inplane = max(bb.xlen, bb.zlen)
        thin = bb.ylen
        is_blade = (thin <= 20.0 and long_inplane >= 150.0)
        (blade_idxs if is_blade else other_idxs).append(i)
        print(f"Solid[{i}] bb=({bb.xlen:.2f},{bb.ylen:.2f},{bb.zlen:.2f}) -> {'blade' if is_blade else 'other'}")

    print(f"Blade solids selected: {blade_idxs}")
    print(f"Non-blade solids: {other_idxs}")

    # Determine central window size for thinning from the clamp-ish body if present
    window_size = 60.0
    if other_idxs:
        bb_o = solids[other_idxs[0]].BoundingBox()
        window_size = max(bb_o.xlen, bb_o.zlen) + 10.0
    window_size = max(40.0, float(window_size))
    print(f"Central thinning window size (square in rotor plane): {window_size:.2f} mm")

    # fillet radii attempts (mm) - keep modest because of thin 0.42mm central web
    radii_try = [0.35, 0.30, 0.25, 0.20, 0.15, 0.10]

    # compute basis for angles
    u, v, _ = plane_basis(axis_dir)

    # compute blade in-plane directions/angles
    blade_dirs = {}
    blade_angles = {}
    for bi in blade_idxs:
        dlen = v_unit(blade_dir_from_vertices(solids[bi], global_center, axis_dir))
        ang = dir_to_line_angle_deg(dlen, u, v)
        blade_dirs[bi] = dlen
        blade_angles[bi] = ang
        print(f"Blade[{bi}] angle(line, mod180)≈{ang:.2f}°, dlen={dlen}")

    # add third blade if exactly two blade solids
    new_blade = None
    if len(blade_idxs) == 2:
        existing_angles = [blade_angles[i] for i in blade_idxs]
        targets, new_ang = best_three_line_pattern(existing_angles, step=0.25)
        if new_ang is None:
            # fallback: maximize distance
            best_a, best_d = 0.0, -1.0
            a = 0.0
            while a < 180.0 - 1e-9:
                mind = min(ang_dist_180(a, ea) for ea in existing_angles)
                if mind > best_d:
                    best_d = mind
                    best_a = a
                a += 0.5
            new_ang = best_a
            print(f"Pattern fit failed; fallback new angle≈{new_ang:.2f}°")
        else:
            print(f"3-line targets≈{[round(t,2) for t in targets]}, chosen new≈{new_ang:.2f}°")

        # pick a template blade to duplicate
        # To better honor 'same design', choose the blade whose bbox thickness matches (should be same),
        # and prefer the one with larger volume (usually the full blade body).
        def vol_safe(s):
            try:
                return float(s.Volume())
            except Exception:
                bb = s.BoundingBox()
                return bb.xlen * bb.ylen * bb.zlen

        template_idx = max(blade_idxs, key=lambda i: vol_safe(solids[i]))
        template = solids[template_idx]
        template_ang = blade_angles[template_idx]
        delta = new_ang - template_ang

        p1 = v_add(global_center, v_mul(axis_dir, -1000.0))
        p2 = v_add(global_center, v_mul(axis_dir, +1000.0))
        print(
            f"Duplicating Solid[{template_idx}] as new blade: template_ang≈{template_ang:.2f}°, new_ang≈{new_ang:.2f}°, rotate delta≈{delta:.2f}°"
        )
        try:
            new_blade = (template.copy() if hasattr(template, "copy") else template).rotate(p1, p2, delta)
        except Exception as e:
            print(f"New blade rotation failed ({e}); using 60° fallback")
            new_blade = (template.copy() if hasattr(template, "copy") else template).rotate(p1, p2, 60.0)

    elif len(blade_idxs) >= 3:
        print("3 or more blade-like solids already present; not adding another blade.")

    # Build output solids
    out_solids = []
    for oi in other_idxs:
        out_solids.append(solids[oi])

    target_t = 0.42

    # process existing blades: thin central portion and fillet four long-edge groups (including segmented edges)
    for bi in blade_idxs:
        b = solids[bi]
        try:
            b = thin_central_portion_box(b, global_center, axis_dir, window_size, target_thickness=target_t)
            print(f"Blade[{bi}] central portion thinned to ~{target_t}mm")
        except Exception as e:
            print(f"Blade[{bi}] thinning failed: {e}")

        try:
            dlen = blade_dirs.get(bi, v_unit(blade_dir_from_vertices(b, global_center, axis_dir)))
            edges = long_edge_segments_4groups(b, global_center, axis_dir, dlen)
            print(f"Blade[{bi}] long-edge segments selected for fillet: {len(edges)}")
            b2, ok = fillet_edges_safe(b, edges, radii_try)
            print(f"Blade[{bi}] fillet applied: {ok}")
            out_solids.append(b2)
        except Exception as e:
            print(f"Blade[{bi}] fillet failed: {e}")
            out_solids.append(b)

    # process new blade similarly
    if new_blade is not None:
        nb = new_blade
        try:
            nb = thin_central_portion_box(nb, global_center, axis_dir, window_size, target_thickness=target_t)
            print(f"New blade central portion thinned to ~{target_t}mm")
        except Exception as e:
            print(f"New blade thinning failed: {e}")

        try:
            nb_dlen = v_unit(blade_dir_from_vertices(nb, global_center, axis_dir))
            nb_edges = long_edge_segments_4groups(nb, global_center, axis_dir, nb_dlen)
            print(f"New blade long-edge segments selected for fillet: {len(nb_edges)}")
            nb2, ok = fillet_edges_safe(nb, nb_edges, radii_try)
            print(f"New blade fillet applied: {ok}")
            out_solids.append(nb2)
        except Exception as e:
            print(f"New blade fillet failed: {e}")
            out_solids.append(nb)

    print(f"Solid count (output): {len(out_solids)}")
    return cq.Compound.makeCompound(out_solids)
